function makeGuide(seed: Guide): Post {
  const world = worlds.find((item) => item.slug === seed.cluster);
  if (!world) throw new Error(`unknown guide world: ${seed.cluster}`);
  const pillar = {
    space:'sourojogoter-groho', physics:'sorol-jontro-kake-bole', chemistry:'podarther-obostha',
    life:'salokshongshleshon-kake-bole', nature:'chhoy-ritu-baro-mash', food:'khaddyer-upadan',
    math:'bhognangsho-doshomik-shotokra', money:'shishuke-takar-hisab-shekhano', language:'bangla-bornomala-shekhano',
    social:'shishur-rag-samlano', discovery:'ghore-boshe-biggan-porikkha',
  }[seed.cluster];
  return {
    ...seed,
    updated:'2026-10-04', generatedCover:true,
    refs:[
      {label:`${world.bn} ভুবনে বিষয়টি খুঁজে দেখো`,href:`/${world.slug}/#all`,note:'এই ভুবনের বিভাগ ও হাতে-কলমে শেখার মডেল দেখো।'},
      {label:`${world.bn} ভুবনের মূল পরিচিতি`,href:`/blog/${pillar}/`,note:'ভুবনের কেন্দ্রীয় ধারণাগুলো দিয়ে শুরু করো।'},
      EDITORIAL_SOURCES[seed.cluster],
    ],
  };
}

export default guides.map(makeGuide);
